#!/bin/bash
for id in cal-leo-park@northwind.example planning-chi@northwind.example planning-la@northwind.example planning-ny@northwind.example planning-parker@northwind.example planning-shared@northwind.example jordan.lee@northwind.example; do
  enc=$(python3 -c "import urllib.parse,sys; print(urllib.parse.quote(sys.argv[1], safe=''))" "$id")
  echo "=== $id ==="
  curl -s "https://www.googleapis.com/calendar/v3/calendars/${enc}/events?q=lunch&singleEvents=true&timeMin=2018-06-17T00:00:00-05:00&timeMax=2019-01-01T00:00:00-05:00&orderBy=startTime&maxResults=100" -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys,datetime
d=json.load(sys.stdin)
items=d.get('items',[])
print('count:', len(items), '| tz:', d.get('timeZone'))
def wd(i):
    s=i.get('start',{})
    t=s.get('dateTime') or s.get('date')
    if t and 'T' in t:
        dt=datetime.datetime.fromisoformat(t.replace('Z','+00:00'))
        return dt.strftime('%a %Y-%m-%d %H:%M %z')
    return str(t)
for i in items:
    print(' ', i.get('id'), '|', wd(i), '|', i.get('summary'), '|', i.get('location'))
"
done
